import math
from typing import Callable, Hashable, Sequence, Tuple

KB, T = 1.380649e-23, 300.0

def image_card(f: Callable[[Hashable], Hashable], dom: Sequence[Hashable]) -> int:
    return len({f(x) for x in dom})

def erased_bits(f: Callable[[Hashable], Hashable], dom: Sequence[Hashable]) -> float:
    return math.log2(len(dom)) - math.log2(image_card(f, dom))

def landauer(bits: float) -> float:
    return bits * KB * T * math.log(2.0)

def and_gate(b: Tuple[int, int]) -> int:
    return b[0] & b[1]

def not_gate(b: int) -> int:
    return 1 - b

and_dom = [(a, b) for a in (0, 1) for b in (0, 1)]
print("AND:", erased_bits(and_gate, and_dom), "bit ->", landauer(erased_bits(and_gate, and_dom)), "J")
print("NOT:", erased_bits(not_gate, [0, 1]), "bit (reversible)")

import math
from typing import Callable, Hashable, List, Sequence

def image_card(f, dom): return len({f(x) for x in dom})
def compose(fs):
    def g(x):
        for f in fs: x = f(x)
        return x
    return g

def clausius(fs: Sequence[Callable], dom: Sequence[Hashable]) -> List[float]:
    drops = []
    for i in range(len(fs)):
        before = image_card(compose(fs[:i]), dom)
        after = image_card(compose(fs[:i+1]), dom)
        drops.append(math.log2(before) - math.log2(after))
    return drops

def total_erased(fs, dom):
    return math.log2(len(dom)) - math.log2(image_card(compose(fs), dom))

dom = list(range(8))
fs = [lambda x: x % 4, lambda x: x % 2, lambda x: 0]
d = clausius(fs, dom)
print("per-step productions:", d)
print("sum =", sum(d), " total_erased =", total_erased(fs, dom))
assert abs(sum(d) - total_erased(fs, dom)) < 1e-12

import math
from typing import Callable, Hashable, Sequence, Tuple

def image_card(f, dom): return len({f(x) for x in dom})
def erased_bits(f, dom): return math.log2(len(dom)) - math.log2(image_card(f, dom))
def created_bits(a: int, b: int) -> float: return math.log2(b) - math.log2(a)

def bennett_ledger(f: Callable, dom: Sequence[Hashable], codomain: int) -> Tuple[float, float]:
    dilation = lambda x: (x, f(x))
    return erased_bits(dilation, list(dom)), created_bits(len(dom), len(dom) * codomain)

and_dom = [(a, b) for a in (0, 1) for b in (0, 1)]
erased, created = bennett_ledger(lambda b: b[0] & b[1], and_dom, 2)
print("erased =", erased, " created =", created, "= log2(codomain)")

