from typing import Callable, Hashable, Optional, Sequence, Tuple

def certify_reversible(
    register: Sequence[Hashable],
    fs: Sequence[Callable[[Hashable], Hashable]],
) -> Tuple[bool, Optional[int]]:
    """Return (is_reversible, index_of_first_irreversible_step)."""
    cur = set(register)
    for i, f in enumerate(fs, start=1):
        nxt = {f(x) for x in cur}
        if len(nxt) < len(cur):
            return (False, i)
        cur = nxt
    return (True, None)
